window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-74b7d013a949c865"]={"versions": [{"id": "FIG-74b7d013a949c865", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Metamodell-Klassendiagramm aus der AUTOSAR Adaptive Platform (<em>TPS_ManifestSpecification</em>, R21-11).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der DDS-Security-Konfiguration (konform zur OMG DDS Security Specification) auf Ebene des Deployment- und Machine-Mappings.</li>\n<li><strong>Funktionale Einordnung:</strong> Verknüpft Service-Instanzen (<code>ara::com</code> über DDS-Transport-Binding) und Netzwerkschnittstellen (<code>CommunicationConnector</code>) auf einer konkreten Maschine mit Sicherheitsrichtlinien (<code>DdsSecureGovernance</code>), Identitätszertifikaten (<code>CryptoCertificate</code>) und Schutzklassen (<code>DdsProtectionKindEnum</code>) für den DDS-Domain-Participant.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen und Hierarchien</p>\n<ul class=\"fig-list\">\n<li><strong><code>ServiceInstanceToMachineMapping</code></strong> <em>(UploadablePackageElement, abstrakt)</em>: Basisklasse für die Zuweisung logischer Service-Instanzen zu einer physischen Maschine.</li>\n<li><code>serviceInstance</code> (0..\\*): Assoziation zu <code>AdaptivePlatformServiceInstance</code>.</li>\n<li><code>communicationConnector</code> (0..1): Bindung an den physischen/logischen Netzwerk-Port (<code>CommunicationConnector</code>, abgeleitet von <code>Identifiable</code>).</li>\n<li><code>secureComPropsForUdp</code> / <code>secureComPropsForTcp</code> (je 0..1): Optionale generische Security-Eigenschaften für Transportprotokolle.</li>\n<li><strong><code>DdsServiceInstanceToMachineMapping</code></strong> <em>(spezialisiert <code>ServiceInstanceToMachineMapping</code>)</em>:</li>\n<li>Konkrete Ausprägung für das DDS-Transport-Binding.</li>\n<li><code>secureComPropsForDds</code> (0..1): Referenz auf DDS-spezifische Sicherheitsattribute (<code>DdsSecureComProps</code>).</li>\n<li><strong><code>SecureComProps</code></strong> <em>(ARElement, abstrakt)</em>: Übergreifende Basis-Metaklasse für abgesicherte Kommunikationskanäle.</li>\n<li><strong><code>DdsSecureComProps</code></strong> <em>(spezialisiert <code>SecureComProps</code>)</em>:</li>\n<li>Bündelt die DDS-Security-Konfiguration für einen Participant.</li>\n<li><code>identity</code> (0..1): Assoziation zu <code>CryptoCertificate</code> (repräsentiert das Identitätszertifikat des lokalen DDS-Endpoints/Participants).</li>\n<li><code>governance</code> (0..1): Assoziation zur Sicherheitsrichtlinie <code>DdsSecureGovernance</code>.</li>\n<li><strong><code>DdsSecureGovernance</code></strong> <em>(UploadablePackageElement)</em>:</li>\n<li>Definiert die globalen Domain-Regeln des DDS-Sicherheitsmodells.</li>\n<li>Attribute:</li>\n<li><code>allowUnauthenticatedParticipants: Boolean [0..1]</code>: Steuert, ob nicht authentifizierte Teilnehmer der Domain beitreten dürfen.</li>\n<li><code>enableJoinAccessControl: Boolean [0..1]</code>: Aktiviert die rollenbasierte Zugriffskontrolle für den Domain-Beitritt.</li>\n<li><code>discoveryProtectionKind: DdsProtectionKindEnum [0..1]</code>: Schutzgrad des DDS-Discovery-Verkehrs (SEDP/SPDP).</li>\n<li><code>livelinessProtectionKind: DdsProtectionKindEnum [0..1]</code>: Schutzgrad der Liveliness-Assertions.</li>\n<li><code>rtpsProtectionKind: DdsProtectionKindEnum [0..1]</code>: Schutzgrad von RTPS-Nachrichten/Payloads.</li>\n<li>Assoziationen:</li>\n<li><code>identityCertificateAuthority</code> (0..1): Vertrauensanker (Root-CA) zur Validierung fremder Teilnehmerzertifikate (<code>CryptoCertificate</code>).</li>\n<li><code>permissionCertificateAuthority</code> (0..1): Vertrauensanker (Permissions-CA) zur Validierung von Berechtigungsdokumenten (<code>CryptoCertificate</code>).</li>\n<li><code>domainId</code> (0..\\*, Komposition): Aggregiert gültige DDS-Domänenbereiche via <code>DdsDomainRange</code>.</li>\n<li><strong><code>DdsDomainRange</code></strong> <em>(Identifiable)</em>:</li>\n<li>Schränkt die Gültigkeit der Governance-Regeln auf DDS-Domain-IDs ein.</li>\n<li>Attribute: <code>min: PositiveInteger [0..1]</code>, <code>max: PositiveInteger [0..1]</code>.</li>\n<li><strong><code>CryptoCertificate</code></strong> <em>(Identifiable)</em>:</li>\n<li>Abstraktion des X.509-Zertifikats im Manifest; referenziert Schlüsselmaterial im AUTOSAR Crypto Stack.</li>\n<li>Attribut: <code>isPrivate: Boolean [0..1]</code>.</li>\n<li><strong><code>«enumeration» DdsProtectionKindEnum</code></strong>:</li>\n<li><code>none</code>: Kein kryptografischer Schutz.</li>\n<li><code>sign</code>: Integritätsschutz via Signaturen/HMAC.</li>\n<li><code>encryptAndSign</code>: Vertraulichkeit und Integrität.</li>\n<li><code>signWithOriginAuthentication</code>: Signatur mit kryptografischem Nachweis des Senderursprungs.</li>\n<li><code>encryptAndSignWithOriginAuthentication</code>: Vollständige Verschlüsselung inklusive Senderauthentifizierung.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell handelt, manifestiert sich das Verhalten zur Laufzeit während des Plattform-Bootstraps und Verbindungsaufbaus:</p>\n<ol class=\"fig-list\">\n<li><strong>Deployment & Initialisierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Plattform-Management-/Execution-Management-Dienst parst das Manifest.</li>\n<li>Der DDS-Binding-Stack (z. B. RTI Connext Drive, FastDDS) instantiiert den <code>DomainParticipant</code> innerhalb des durch <code>DdsDomainRange</code> [min..max] definierten Bereichs.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kryptografische Vorkonfiguration:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Abruf des privaten Identitätszertifikats (<code>identity</code>) und der Root-CAs (<code>identityCertificateAuthority</code>, <code>permissionCertificateAuthority</code>) über die Schnittstellen von <code>ara::crypto</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>DDS Security Plugin Handshake (OMG DDS-SEC):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Authentication:</strong> Validierung der Remote-Participants gegen <code>identityCertificateAuthority</code>. Bei Fehlschlag Prüfung von <code>allowUnauthenticatedParticipants</code>.</li>\n<li><strong>Access Control:</strong> Auswertung von <code>enableJoinAccessControl</code> und Validierung von Berechtigungstoken gegen <code>permissionCertificateAuthority</code>.</li>\n<li><strong>Crypto Exchange:</strong> Aushandlung symmetrischer Sitzungsschlüssel basierend auf den Vorgaben für <code>discoveryProtectionKind</code>, <code>livelinessProtectionKind</code> und <code>rtpsProtectionKind</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Verkehrsabsicherung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Jeder RTPS-Submessage-Header bzw. Payload wird entsprechend des konfigurierten <code>DdsProtectionKindEnum</code> signiert, verschlüsselt oder ungeschützt übertragen. Bei Sicherheitsverletzungen erfolgt der Abbruch des Handshakes und optionales Reporting an das IDS (Intrusion Detection System / <code>ara::idsm</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Modellierung (ARXML):</strong></li>\n<li>Durch Vererbung von <code>UploadablePackageElement</code> können <code>DdsSecureGovernance</code> und Service-Mappings unabhängig von der Applikations-Binärdatei über das Update and Configuration Management (<code>ara::ucm</code>) aktualisiert werden (z. B. bei CA-Rollover oder geänderten Schutzklassen).</li>\n<li><strong>Stack- und Middleware-Entwickler:</strong></li>\n<li>Der DDS-Code-Generator muss aus <code>DdsSecureGovernance</code> die standardisierten OMG-DDS-SEC-XML-Dokumente (<code>governance.xml</code> und <code>permissions.xml</code>) generieren oder native Middleware-Properties konfigurieren.</li>\n<li><code>isPrivate = true</code> am <code>CryptoCertificate</code> signalisiert dem Deployment-Tooling, dass neben dem Zertifikat auch ein privater Schlüssel (Key Slot) im Crypto Stack gebunden sein muss.</li>\n<li><strong>Ressourcen- und Laufzeitimplikationen (Embedded/Safety):</strong></li>\n<li>Die Wahl von <code>encryptAndSignWithOriginAuthentication</code> in <code>rtpsProtectionKind</code> führt zu signifikantem CPU-Overhead und Latenzanstieg pro RTPS-Paket; erfordert zwingend Hardware-Krypto-Beschleunigung (z. B. über HSM/SHE-Anbindung an <code>ara::crypto</code>).</li>\n<li>Eine Fehlkonfiguration der <code>DdsDomainRange</code> verhindert die Discovery zwischen Service-Provider und Consumer vollständig, ohne dass funktionale Kommunikationsfehler auf API-Ebene (<code>ara::com</code>) differenziert gemeldet werden.</li>\n</ul>"}, {"id": "FIG-e285811befa1ac49", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Metamodell-Klassendiagramm aus der AUTOSAR Adaptive Platform (<em>TPS_ManifestSpecification</em>, R21-11).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der DDS-Security-Konfiguration (konform zur OMG DDS Security Specification) auf Ebene des Deployment- und Machine-Mappings.</li>\n<li><strong>Funktionale Einordnung:</strong> Verknüpft Service-Instanzen (<code>ara::com</code> über DDS-Transport-Binding) und Netzwerkschnittstellen (<code>CommunicationConnector</code>) auf einer konkreten Maschine mit Sicherheitsrichtlinien (<code>DdsSecureGovernance</code>), Identitätszertifikaten (<code>CryptoCertificate</code>) und Schutzklassen (<code>DdsProtectionKindEnum</code>) für den DDS-Domain-Participant.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen und Hierarchien</p>\n<ul class=\"fig-list\">\n<li><strong><code>ServiceInstanceToMachineMapping</code></strong> <em>(UploadablePackageElement, abstrakt)</em>: Basisklasse für die Zuweisung logischer Service-Instanzen zu einer physischen Maschine.</li>\n<li><code>serviceInstance</code> (0..\\*): Assoziation zu <code>AdaptivePlatformServiceInstance</code>.</li>\n<li><code>communicationConnector</code> (0..1): Bindung an den physischen/logischen Netzwerk-Port (<code>CommunicationConnector</code>, abgeleitet von <code>Identifiable</code>).</li>\n<li><code>secureComPropsForUdp</code> / <code>secureComPropsForTcp</code> (je 0..1): Optionale generische Security-Eigenschaften für Transportprotokolle.</li>\n<li><strong><code>DdsServiceInstanceToMachineMapping</code></strong> <em>(spezialisiert <code>ServiceInstanceToMachineMapping</code>)</em>:</li>\n<li>Konkrete Ausprägung für das DDS-Transport-Binding.</li>\n<li><code>secureComPropsForDds</code> (0..1): Referenz auf DDS-spezifische Sicherheitsattribute (<code>DdsSecureComProps</code>).</li>\n<li><strong><code>SecureComProps</code></strong> <em>(ARElement, abstrakt)</em>: Übergreifende Basis-Metaklasse für abgesicherte Kommunikationskanäle.</li>\n<li><strong><code>DdsSecureComProps</code></strong> <em>(spezialisiert <code>SecureComProps</code>)</em>:</li>\n<li>Bündelt die DDS-Security-Konfiguration für einen Participant.</li>\n<li><code>identity</code> (0..1): Assoziation zu <code>CryptoCertificate</code> (repräsentiert das Identitätszertifikat des lokalen DDS-Endpoints/Participants).</li>\n<li><code>governance</code> (0..1): Assoziation zur Sicherheitsrichtlinie <code>DdsSecureGovernance</code>.</li>\n<li><strong><code>DdsSecureGovernance</code></strong> <em>(UploadablePackageElement)</em>:</li>\n<li>Definiert die globalen Domain-Regeln des DDS-Sicherheitsmodells.</li>\n<li>Attribute:</li>\n<li><code>allowUnauthenticatedParticipants: Boolean [0..1]</code>: Steuert, ob nicht authentifizierte Teilnehmer der Domain beitreten dürfen.</li>\n<li><code>enableJoinAccessControl: Boolean [0..1]</code>: Aktiviert die rollenbasierte Zugriffskontrolle für den Domain-Beitritt.</li>\n<li><code>discoveryProtectionKind: DdsProtectionKindEnum [0..1]</code>: Schutzgrad des DDS-Discovery-Verkehrs (SEDP/SPDP).</li>\n<li><code>livelinessProtectionKind: DdsProtectionKindEnum [0..1]</code>: Schutzgrad der Liveliness-Assertions.</li>\n<li><code>rtpsProtectionKind: DdsProtectionKindEnum [0..1]</code>: Schutzgrad von RTPS-Nachrichten/Payloads.</li>\n<li>Assoziationen:</li>\n<li><code>identityCertificateAuthority</code> (0..1): Vertrauensanker (Root-CA) zur Validierung fremder Teilnehmerzertifikate (<code>CryptoCertificate</code>).</li>\n<li><code>permissionCertificateAuthority</code> (0..1): Vertrauensanker (Permissions-CA) zur Validierung von Berechtigungsdokumenten (<code>CryptoCertificate</code>).</li>\n<li><code>domainId</code> (0..\\*, Komposition): Aggregiert gültige DDS-Domänenbereiche via <code>DdsDomainRange</code>.</li>\n<li><strong><code>DdsDomainRange</code></strong> <em>(Identifiable)</em>:</li>\n<li>Schränkt die Gültigkeit der Governance-Regeln auf DDS-Domain-IDs ein.</li>\n<li>Attribute: <code>min: PositiveInteger [0..1]</code>, <code>max: PositiveInteger [0..1]</code>.</li>\n<li><strong><code>CryptoCertificate</code></strong> <em>(Identifiable)</em>:</li>\n<li>Abstraktion des X.509-Zertifikats im Manifest; referenziert Schlüsselmaterial im AUTOSAR Crypto Stack.</li>\n<li>Attribut: <code>isPrivate: Boolean [0..1]</code>.</li>\n<li><strong><code>«enumeration» DdsProtectionKindEnum</code></strong>:</li>\n<li><code>none</code>: Kein kryptografischer Schutz.</li>\n<li><code>sign</code>: Integritätsschutz via Signaturen/HMAC.</li>\n<li><code>encryptAndSign</code>: Vertraulichkeit und Integrität.</li>\n<li><code>signWithOriginAuthentication</code>: Signatur mit kryptografischem Nachweis des Senderursprungs.</li>\n<li><code>encryptAndSignWithOriginAuthentication</code>: Vollständige Verschlüsselung inklusive Senderauthentifizierung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell handelt, manifestiert sich das Verhalten zur Laufzeit während des Plattform-Bootstraps und Verbindungsaufbaus:</p>\n<ol class=\"fig-list\">\n<li><strong>Deployment & Initialisierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Plattform-Management-/Execution-Management-Dienst parst das Manifest.</li>\n<li>Der DDS-Binding-Stack (z. B. RTI Connext Drive, FastDDS) instantiiert den <code>DomainParticipant</code> innerhalb des durch <code>DdsDomainRange</code> [min..max] definierten Bereichs.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kryptografische Vorkonfiguration:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Abruf des privaten Identitätszertifikats (<code>identity</code>) und der Root-CAs (<code>identityCertificateAuthority</code>, <code>permissionCertificateAuthority</code>) über die Schnittstellen von <code>ara::crypto</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>DDS Security Plugin Handshake (OMG DDS-SEC):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Authentication:</strong> Validierung der Remote-Participants gegen <code>identityCertificateAuthority</code>. Bei Fehlschlag Prüfung von <code>allowUnauthenticatedParticipants</code>.</li>\n<li><strong>Access Control:</strong> Auswertung von <code>enableJoinAccessControl</code> und Validierung von Berechtigungstoken gegen <code>permissionCertificateAuthority</code>.</li>\n<li><strong>Crypto Exchange:</strong> Aushandlung symmetrischer Sitzungsschlüssel basierend auf den Vorgaben für <code>discoveryProtectionKind</code>, <code>livelinessProtectionKind</code> und <code>rtpsProtectionKind</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Verkehrsabsicherung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Jeder RTPS-Submessage-Header bzw. Payload wird entsprechend des konfigurierten <code>DdsProtectionKindEnum</code> signiert, verschlüsselt oder ungeschützt übertragen. Bei Sicherheitsverletzungen erfolgt der Abbruch des Handshakes und optionales Reporting an das IDS (Intrusion Detection System / <code>ara::idsm</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Modellierung (ARXML):</strong></li>\n<li>Durch Vererbung von <code>UploadablePackageElement</code> können <code>DdsSecureGovernance</code> und Service-Mappings unabhängig von der Applikations-Binärdatei über das Update and Configuration Management (<code>ara::ucm</code>) aktualisiert werden (z. B. bei CA-Rollover oder geänderten Schutzklassen).</li>\n<li><strong>Stack- und Middleware-Entwickler:</strong></li>\n<li>Der DDS-Code-Generator muss aus <code>DdsSecureGovernance</code> die standardisierten OMG-DDS-SEC-XML-Dokumente (<code>governance.xml</code> und <code>permissions.xml</code>) generieren oder native Middleware-Properties konfigurieren.</li>\n<li><code>isPrivate = true</code> am <code>CryptoCertificate</code> signalisiert dem Deployment-Tooling, dass neben dem Zertifikat auch ein privater Schlüssel (Key Slot) im Crypto Stack gebunden sein muss.</li>\n<li><strong>Ressourcen- und Laufzeitimplikationen (Embedded/Safety):</strong></li>\n<li>Die Wahl von <code>encryptAndSignWithOriginAuthentication</code> in <code>rtpsProtectionKind</code> führt zu signifikantem CPU-Overhead und Latenzanstieg pro RTPS-Paket; erfordert zwingend Hardware-Krypto-Beschleunigung (z. B. über HSM/SHE-Anbindung an <code>ara::crypto</code>).</li>\n<li>Eine Fehlkonfiguration der <code>DdsDomainRange</code> verhindert die Discovery zwischen Service-Provider und Consumer vollständig, ohne dass funktionale Kommunikationsfehler auf API-Ebene (<code>ara::com</code>) differenziert gemeldet werden.</li>\n</ul>"}, {"id": "FIG-5d47f54366f774d6", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Metamodell-Klassendiagramm aus der AUTOSAR Adaptive Platform (<em>TPS_ManifestSpecification</em>, R21-11).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der DDS-Security-Konfiguration (konform zur OMG DDS Security Specification) auf Ebene des Deployment- und Machine-Mappings.</li>\n<li><strong>Funktionale Einordnung:</strong> Verknüpft Service-Instanzen (<code>ara::com</code> über DDS-Transport-Binding) und Netzwerkschnittstellen (<code>CommunicationConnector</code>) auf einer konkreten Maschine mit Sicherheitsrichtlinien (<code>DdsSecureGovernance</code>), Identitätszertifikaten (<code>CryptoCertificate</code>) und Schutzklassen (<code>DdsProtectionKindEnum</code>) für den DDS-Domain-Participant.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen und Hierarchien</p>\n<ul class=\"fig-list\">\n<li><strong><code>ServiceInstanceToMachineMapping</code></strong> <em>(UploadableDesignElement, abstrakt)</em>: Basisklasse für die Zuweisung logischer Service-Instanzen zu einer physischen Maschine.</li>\n<li><code>serviceInstance</code> (0..*): Assoziation zu <code>AdaptivePlatformServiceInstance</code>.</li>\n<li><code>communicationConnector</code> (0..1): Bindung an den physischen/logischen Netzwerk-Port (<code>CommunicationConnector</code>, abgeleitet von <code>Identifiable</code>).</li>\n<li><code>secureComPropsForUdp</code> / <code>secureComPropsForTcp</code> (je 0..1): Optionale generische Security-Eigenschaften für Transportprotokolle.</li>\n<li><strong><code>DdsServiceInstanceToMachineMapping</code></strong> <em>(spezialisiert <code>ServiceInstanceToMachineMapping</code>)</em>:</li>\n<li>Konkrete Ausprägung für das DDS-Transport-Binding.</li>\n<li><code>secureComPropsForDds</code> (0..1): Referenz auf DDS-spezifische Sicherheitsattribute (<code>DdsSecureComProps</code>).</li>\n<li><strong><code>SecureComProps</code></strong> <em>(ARElement, UploadableDesignElement, abstrakt)</em>: Übergreifende Basis-Metaklasse für abgesicherte Kommunikationskanäle.</li>\n<li><strong><code>DdsSecureComProps</code></strong> <em>(spezialisiert <code>SecureComProps</code>)</em>:</li>\n<li>Bündelt die DDS-Security-Konfiguration für einen Participant.</li>\n<li><code>identity</code> (0..1): Assoziation zu <code>CryptoCertificate</code> (repräsentiert das Identitätszertifikat des lokalen DDS-Endpoints/Participants).</li>\n<li><code>governance</code> (0..1): Assoziation zur Sicherheitsrichtlinie <code>DdsSecureGovernance</code>.</li>\n<li><strong><code>DdsSecureGovernance</code></strong> <em>(UploadableDesignElement)</em>:</li>\n<li>Definiert die globalen Domain-Regeln des DDS-Sicherheitsmodells.</li>\n<li>Attribute:</li>\n<li><code>allowUnauthenticatedParticipants: Boolean [0..1]</code>: Steuert, ob nicht authentifizierte Teilnehmer der Domain beitreten dürfen.</li>\n<li><code>enableJoinAccessControl: Boolean [0..1]</code>: Aktiviert die rollenbasierte Zugriffskontrolle für den Domain-Beitritt.</li>\n<li><code>discoveryProtectionKind: DdsProtectionKindEnum [0..1]</code>: Schutzgrad des DDS-Discovery-Verkehrs (SEDP/SPDP).</li>\n<li><code>livelinessProtectionKind: DdsProtectionKindEnum [0..1]</code>: Schutzgrad der Liveliness-Assertions.</li>\n<li><code>rtpsProtectionKind: DdsProtectionKindEnum [0..1]</code>: Schutzgrad von RTPS-Nachrichten/Payloads.</li>\n<li>Assoziationen:</li>\n<li><code>identityCertificateAuthority</code> (0..1): Vertrauensanker (Root-CA) zur Validierung fremder Teilnehmerzertifikate (<code>CryptoCertificate</code>).</li>\n<li><code>permissionCertificateAuthority</code> (0..1): Vertrauensanker (Permissions-CA) zur Validierung von Berechtigungsdokumenten (<code>CryptoCertificate</code>).</li>\n<li><code>domainId</code> (0..*, Komposition): Aggregiert gültige DDS-Domänenbereiche via <code>DdsDomainRange</code>.</li>\n<li><strong><code>DdsDomainRange</code></strong> <em>(Identifiable)</em>:</li>\n<li>Schränkt die Gültigkeit der Governance-Regeln auf DDS-Domain-IDs ein.</li>\n<li>Attribute: <code>min: PositiveInteger [0..1]</code>, <code>max: PositiveInteger [0..1]</code>.</li>\n<li><strong><code>CryptoCertificate</code></strong> <em>(Identifiable)</em>:</li>\n<li>Abstraktion des X.509-Zertifikats im Manifest; referenziert Schlüsselmaterial im AUTOSAR Crypto Stack.</li>\n<li>Attribut: <code>isPrivate: Boolean [0..1]</code> (kennzeichnet, ob das Zertifikat privat/geheim zu halten ist bzw. den privaten Schlüssel repräsentiert).</li>\n<li><strong><code>DdsProtectionKindEnum</code></strong> <em>(«enumeration»)</em>:</li>\n<li>Schutzarten gemäß OMG DDS Security Specification mit den Literalen:</li>\n<li><code>none</code>: Ungeschützte Übertragung.</li>\n<li><code>sign</code>: Integritätsschutz durch kryptografische Signatur.</li>\n<li><code>encryptAndSign</code>: Vertraulichkeit und Integrität durch Verschlüsselung und Signatur.</li>\n<li><code>signWithOriginAuthentication</code>: Signatur mit Authentifizierung des Nachrichtenursprungs.</li>\n<li><code>encryptAndSignWithOriginAuthentication</code>: Verschlüsselung und Signatur mit Authentifizierung des Nachrichtenursprungs.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell handelt, manifestiert sich das Verhalten zur Laufzeit während des Plattform-Bootstraps und Verbindungsaufbaus:</p>\n<ol class=\"fig-list\">\n<li><strong>Deployment & Initialisierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Plattform-Management-/Execution-Management-Dienst parst das Manifest.</li>\n<li>Der DDS-Binding-Stack (z. B. RTI Connext Drive, FastDDS) instantiiert den <code>DomainParticipant</code> innerhalb des durch <code>DdsDomainRange</code> [min..max] definierten Bereichs.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kryptografische Vorkonfiguration:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Abruf des privaten Identitätszertifikats (<code>identity</code>) und der Root-CAs (<code>identityCertificateAuthority</code>, <code>permissionCertificateAuthority</code>) über die Schnittstellen von <code>ara::crypto</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>DDS Security Plugin Handshake (OMG DDS-SEC):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Authentication:</strong> Validierung der Remote-Participants gegen <code>identityCertificateAuthority</code>. Bei Fehlschlag Prüfung von <code>allowUnauthenticatedParticipants</code>.</li>\n<li><strong>Access Control:</strong> Auswertung von <code>enableJoinAccessControl</code> und Validierung von Berechtigungstoken gegen <code>permissionCertificateAuthority</code>.</li>\n<li><strong>Crypto Exchange:</strong> Aushandlung symmetrischer Sitzungsschlüssel basierend auf den Vorgaben für <code>discoveryProtectionKind</code>, <code>livelinessProtectionKind</code> und <code>rtpsProtectionKind</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Verkehrsabsicherung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Jeder RTPS-Submessage-Header bzw. Payload wird entsprechend des konfigurierten <code>DdsProtectionKindEnum</code> signiert, verschlüsselt oder ungeschützt übertragen. Bei Sicherheitsverletzungen erfolgt der Abbruch des Handshakes und optionales Reporting an das IDS (Intrusion Detection System / <code>ara::idsm</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Modellierung (ARXML):</strong></li>\n<li>Durch Vererbung von <code>UploadablePackageElement</code> können <code>DdsSecureGovernance</code> und Service-Mappings unabhängig von der Applikations-Binärdatei über das Update and Configuration Management (<code>ara::ucm</code>) aktualisiert werden (z. B. bei CA-Rollover oder geänderten Schutzklassen).</li>\n<li><strong>Stack- und Middleware-Entwickler:</strong></li>\n<li>Der DDS-Code-Generator muss aus <code>DdsSecureGovernance</code> die standardisierten OMG-DDS-SEC-XML-Dokumente (<code>governance.xml</code> und <code>permissions.xml</code>) generieren oder native Middleware-Properties konfigurieren.</li>\n<li><code>isPrivate = true</code> am <code>CryptoCertificate</code> signalisiert dem Deployment-Tooling, dass neben dem Zertifikat auch ein privater Schlüssel (Key Slot) im Crypto Stack gebunden sein muss.</li>\n<li><strong>Ressourcen- und Laufzeitimplikationen (Embedded/Safety):</strong></li>\n<li>Die Wahl von <code>encryptAndSignWithOriginAuthentication</code> in <code>rtpsProtectionKind</code> führt zu signifikantem CPU-Overhead und Latenzanstieg pro RTPS-Paket; erfordert zwingend Hardware-Krypto-Beschleunigung (z. B. über HSM/SHE-Anbindung an <code>ara::crypto</code>).</li>\n<li>Eine Fehlkonfiguration der <code>DdsDomainRange</code> verhindert die Discovery zwischen Service-Provider und Consumer vollständig, ohne dass funktionale Kommunikationsfehler auf API-Ebene (<code>ara::com</code>) differenziert gemeldet werden.</li>\n</ul>"}, {"id": "FIG-dec460e72c7d220d", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Metamodell-Klassendiagramm aus der AUTOSAR Adaptive Platform (<em>TPS_ManifestSpecification</em>, R21-11).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der DDS-Security-Konfiguration (konform zur OMG DDS Security Specification) auf Ebene des Deployment- und Machine-Mappings.</li>\n<li><strong>Funktionale Einordnung:</strong> Verknüpft Service-Instanzen (<code>ara::com</code> über DDS-Transport-Binding) und Netzwerkschnittstellen (<code>CommunicationConnector</code>) auf einer konkreten Maschine mit Sicherheitsrichtlinien (<code>DdsSecureGovernance</code>), Identitätszertifikaten (<code>CryptoCertificate</code>) und Schutzklassen (<code>DdsProtectionKindEnum</code>) für den DDS-Domain-Participant.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen und Hierarchien</p>\n<ul class=\"fig-list\">\n<li><strong><code>ServiceInstanceToMachineMapping</code></strong> <em>(UploadableDesignElement, abstrakt)</em>: Basisklasse für die Zuweisung logischer Service-Instanzen zu einer physischen Maschine.</li>\n<li><code>serviceInstance</code> (0..*): Assoziation zu <code>AdaptivePlatformServiceInstance</code>.</li>\n<li><code>communicationConnector</code> (0..1): Bindung an den physischen/logischen Netzwerk-Port (<code>CommunicationConnector</code>, abgeleitet von <code>Identifiable</code>).</li>\n<li><code>secureComPropsForUdp</code> / <code>secureComPropsForTcp</code> (je 0..1): Optionale generische Security-Eigenschaften für Transportprotokolle.</li>\n<li><strong><code>DdsServiceInstanceToMachineMapping</code></strong> <em>(spezialisiert <code>ServiceInstanceToMachineMapping</code>)</em>:</li>\n<li>Konkrete Ausprägung für das DDS-Transport-Binding.</li>\n<li><code>secureComPropsForDds</code> (0..1): Referenz auf DDS-spezifische Sicherheitsattribute (<code>DdsSecureComProps</code>).</li>\n<li><strong><code>SecureComProps</code></strong> <em>(ARElement, UploadableDesignElement, abstrakt)</em>: Übergreifende Basis-Metaklasse für abgesicherte Kommunikationskanäle.</li>\n<li><strong><code>DdsSecureComProps</code></strong> <em>(spezialisiert <code>SecureComProps</code>)</em>:</li>\n<li>Bündelt die DDS-Security-Konfiguration für einen Participant.</li>\n<li><code>identity</code> (0..1): Assoziation zu <code>CryptoCertificate</code> (repräsentiert das Identitätszertifikat des lokalen DDS-Endpoints/Participants).</li>\n<li><code>governance</code> (0..1): Assoziation zur Sicherheitsrichtlinie <code>DdsSecureGovernance</code>.</li>\n<li><strong><code>DdsSecureGovernance</code></strong> <em>(UploadableDesignElement)</em>:</li>\n<li>Definiert die globalen Domain-Regeln des DDS-Sicherheitsmodells.</li>\n<li>Attribute:</li>\n<li><code>allowUnauthenticatedParticipants: Boolean [0..1]</code>: Steuert, ob nicht authentifizierte Teilnehmer der Domain beitreten dürfen.</li>\n<li><code>enableJoinAccessControl: Boolean [0..1]</code>: Aktiviert die rollenbasierte Zugriffskontrolle für den Domain-Beitritt.</li>\n<li><code>discoveryProtectionKind: DdsProtectionKindEnum [0..1]</code>: Schutzgrad des DDS-Discovery-Verkehrs (SEDP/SPDP).</li>\n<li><code>livelinessProtectionKind: DdsProtectionKindEnum [0..1]</code>: Schutzgrad der Liveliness-Assertions.</li>\n<li><code>rtpsProtectionKind: DdsProtectionKindEnum [0..1]</code>: Schutzgrad von RTPS-Nachrichten/Payloads.</li>\n<li>Assoziationen:</li>\n<li><code>identityCertificateAuthority</code> (0..1): Vertrauensanker (Root-CA) zur Validierung fremder Teilnehmerzertifikate (<code>CryptoCertificate</code>).</li>\n<li><code>permissionCertificateAuthority</code> (0..1): Vertrauensanker (Permissions-CA) zur Validierung von Berechtigungsdokumenten (<code>CryptoCertificate</code>).</li>\n<li><code>domainId</code> (0..*, Komposition): Aggregiert gültige DDS-Domänenbereiche via <code>DdsDomainRange</code>.</li>\n<li><strong><code>DdsDomainRange</code></strong> <em>(Identifiable)</em>:</li>\n<li>Schränkt die Gültigkeit der Governance-Regeln auf DDS-Domain-IDs ein.</li>\n<li>Attribute: <code>min: PositiveInteger [0..1]</code>, <code>max: PositiveInteger [0..1]</code>.</li>\n<li><strong><code>CryptoCertificate</code></strong> <em>(Identifiable)</em>:</li>\n<li>Abstraktion des X.509-Zertifikats im Manifest; referenziert Schlüsselmaterial im AUTOSAR Crypto Stack.</li>\n<li>Attribut: <code>isPrivate: Boolean [0..1]</code> (kennzeichnet, ob das Zertifikat privat/geheim zu halten ist bzw. den privaten Schlüssel repräsentiert).</li>\n<li><strong><code>DdsProtectionKindEnum</code></strong> <em>(«enumeration»)</em>:</li>\n<li>Schutzarten gemäß OMG DDS Security Specification mit den Literalen:</li>\n<li><code>none</code>: Ungeschützte Übertragung.</li>\n<li><code>sign</code>: Integritätsschutz durch kryptografische Signatur.</li>\n<li><code>encryptAndSign</code>: Vertraulichkeit und Integrität durch Verschlüsselung und Signatur.</li>\n<li><code>signWithOriginAuthentication</code>: Signatur mit Authentifizierung des Nachrichtenursprungs.</li>\n<li><code>encryptAndSignWithOriginAuthentication</code>: Verschlüsselung und Signatur mit Authentifizierung des Nachrichtenursprungs.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell handelt, manifestiert sich das Verhalten zur Laufzeit während des Plattform-Bootstraps und Verbindungsaufbaus:</p>\n<ol class=\"fig-list\">\n<li><strong>Deployment & Initialisierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Plattform-Management-/Execution-Management-Dienst parst das Manifest.</li>\n<li>Der DDS-Binding-Stack (z. B. RTI Connext Drive, FastDDS) instantiiert den <code>DomainParticipant</code> innerhalb des durch <code>DdsDomainRange</code> [min..max] definierten Bereichs.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kryptografische Vorkonfiguration:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Abruf des privaten Identitätszertifikats (<code>identity</code>) und der Root-CAs (<code>identityCertificateAuthority</code>, <code>permissionCertificateAuthority</code>) über die Schnittstellen von <code>ara::crypto</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>DDS Security Plugin Handshake (OMG DDS-SEC):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Authentication:</strong> Validierung der Remote-Participants gegen <code>identityCertificateAuthority</code>. Bei Fehlschlag Prüfung von <code>allowUnauthenticatedParticipants</code>.</li>\n<li><strong>Access Control:</strong> Auswertung von <code>enableJoinAccessControl</code> und Validierung von Berechtigungstoken gegen <code>permissionCertificateAuthority</code>.</li>\n<li><strong>Crypto Exchange:</strong> Aushandlung symmetrischer Sitzungsschlüssel basierend auf den Vorgaben für <code>discoveryProtectionKind</code>, <code>livelinessProtectionKind</code> und <code>rtpsProtectionKind</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Verkehrsabsicherung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Jeder RTPS-Submessage-Header bzw. Payload wird entsprechend des konfigurierten <code>DdsProtectionKindEnum</code> signiert, verschlüsselt oder ungeschützt übertragen. Bei Sicherheitsverletzungen erfolgt der Abbruch des Handshakes und optionales Reporting an das IDS (Intrusion Detection System / <code>ara::idsm</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Modellierung (ARXML):</strong></li>\n<li>Durch Vererbung von <code>UploadablePackageElement</code> können <code>DdsSecureGovernance</code> und Service-Mappings unabhängig von der Applikations-Binärdatei über das Update and Configuration Management (<code>ara::ucm</code>) aktualisiert werden (z. B. bei CA-Rollover oder geänderten Schutzklassen).</li>\n<li><strong>Stack- und Middleware-Entwickler:</strong></li>\n<li>Der DDS-Code-Generator muss aus <code>DdsSecureGovernance</code> die standardisierten OMG-DDS-SEC-XML-Dokumente (<code>governance.xml</code> und <code>permissions.xml</code>) generieren oder native Middleware-Properties konfigurieren.</li>\n<li><code>isPrivate = true</code> am <code>CryptoCertificate</code> signalisiert dem Deployment-Tooling, dass neben dem Zertifikat auch ein privater Schlüssel (Key Slot) im Crypto Stack gebunden sein muss.</li>\n<li><strong>Ressourcen- und Laufzeitimplikationen (Embedded/Safety):</strong></li>\n<li>Die Wahl von <code>encryptAndSignWithOriginAuthentication</code> in <code>rtpsProtectionKind</code> führt zu signifikantem CPU-Overhead und Latenzanstieg pro RTPS-Paket; erfordert zwingend Hardware-Krypto-Beschleunigung (z. B. über HSM/SHE-Anbindung an <code>ara::crypto</code>).</li>\n<li>Eine Fehlkonfiguration der <code>DdsDomainRange</code> verhindert die Discovery zwischen Service-Provider und Consumer vollständig, ohne dass funktionale Kommunikationsfehler auf API-Ebene (<code>ara::com</code>) differenziert gemeldet werden.</li>\n</ul>"}, {"id": "FIG-5a329285d1c21059", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Metamodell-Klassendiagramm aus der AUTOSAR Adaptive Platform (<em>TPS_ManifestSpecification</em>, R21-11).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der DDS-Security-Konfiguration (konform zur OMG DDS Security Specification) auf Ebene des Deployment- und Machine-Mappings.</li>\n<li><strong>Funktionale Einordnung:</strong> Verknüpft Service-Instanzen (<code>ara::com</code> über DDS-Transport-Binding) und Netzwerkschnittstellen (<code>CommunicationConnector</code>) auf einer konkreten Maschine mit Sicherheitsrichtlinien (<code>DdsSecureGovernance</code>), Identitätszertifikaten (<code>CryptoCertificate</code>) und Schutzklassen (<code>DdsProtectionKindEnum</code>) für den DDS-Domain-Participant.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen und Hierarchien</p>\n<ul class=\"fig-list\">\n<li><strong><code>ServiceInstanceToMachineMapping</code></strong> <em>(UploadableDesignElement, abstrakt)</em>: Basisklasse für die Zuweisung logischer Service-Instanzen zu einer physischen Maschine.</li>\n<li><code>serviceInstance</code> (0..*): Assoziation zu <code>AdaptivePlatformServiceInstance</code>.</li>\n<li><code>communicationConnector</code> (0..1): Bindung an den physischen/logischen Netzwerk-Port (<code>CommunicationConnector</code>, abgeleitet von <code>Identifiable</code>).</li>\n<li><code>secureComPropsForUdp</code> / <code>secureComPropsForTcp</code> (je 0..1): Optionale generische Security-Eigenschaften für Transportprotokolle.</li>\n<li><strong><code>DdsServiceInstanceToMachineMapping</code></strong> <em>(spezialisiert <code>ServiceInstanceToMachineMapping</code>)</em>:</li>\n<li>Konkrete Ausprägung für das DDS-Transport-Binding.</li>\n<li><code>secureComPropsForDds</code> (0..1): Referenz auf DDS-spezifische Sicherheitsattribute (<code>DdsSecureComProps</code>).</li>\n<li><strong><code>SecureComProps</code></strong> <em>(ARElement, UploadableDesignElement, abstrakt)</em>: Übergreifende Basis-Metaklasse für abgesicherte Kommunikationskanäle.</li>\n<li><strong><code>DdsSecureComProps</code></strong> <em>(spezialisiert <code>SecureComProps</code>)</em>:</li>\n<li>Bündelt die DDS-Security-Konfiguration für einen Participant.</li>\n<li><code>identity</code> (0..1): Assoziation zu <code>CryptoCertificate</code> (repräsentiert das Identitätszertifikat des lokalen DDS-Endpoints/Participants).</li>\n<li><code>governance</code> (0..1): Assoziation zur Sicherheitsrichtlinie <code>DdsSecureGovernance</code>.</li>\n<li><strong><code>DdsSecureGovernance</code></strong> <em>(UploadableDesignElement)</em>:</li>\n<li>Definiert die globalen Domain-Regeln des DDS-Sicherheitsmodells.</li>\n<li>Attribute:</li>\n<li><code>allowUnauthenticatedParticipants: Boolean [0..1]</code>: Steuert, ob nicht authentifizierte Teilnehmer der Domain beitreten dürfen.</li>\n<li><code>enableJoinAccessControl: Boolean [0..1]</code>: Aktiviert die rollenbasierte Zugriffskontrolle für den Domain-Beitritt.</li>\n<li><code>discoveryProtectionKind: DdsProtectionKindEnum [0..1]</code>: Schutzgrad des DDS-Discovery-Verkehrs (SEDP/SPDP).</li>\n<li><code>livelinessProtectionKind: DdsProtectionKindEnum [0..1]</code>: Schutzgrad der Liveliness-Assertions.</li>\n<li><code>rtpsProtectionKind: DdsProtectionKindEnum [0..1]</code>: Schutzgrad von RTPS-Nachrichten/Payloads.</li>\n<li>Assoziationen:</li>\n<li><code>identityCertificateAuthority</code> (0..1): Vertrauensanker (Root-CA) zur Validierung fremder Teilnehmerzertifikate (<code>CryptoCertificate</code>).</li>\n<li><code>permissionCertificateAuthority</code> (0..1): Vertrauensanker (Permissions-CA) zur Validierung von Berechtigungsdokumenten (<code>CryptoCertificate</code>).</li>\n<li><code>domainId</code> (0..*, Komposition): Aggregiert gültige DDS-Domänenbereiche via <code>DdsDomainRange</code>.</li>\n<li><strong><code>DdsDomainRange</code></strong> <em>(Identifiable)</em>:</li>\n<li>Schränkt die Gültigkeit der Governance-Regeln auf DDS-Domain-IDs ein.</li>\n<li>Attribute: <code>min: PositiveInteger [0..1]</code>, <code>max: PositiveInteger [0..1]</code>.</li>\n<li><strong><code>CryptoCertificate</code></strong> <em>(Identifiable)</em>:</li>\n<li>Abstraktion des X.509-Zertifikats im Manifest; referenziert Schlüsselmaterial im AUTOSAR Crypto Stack.</li>\n<li>Attribut: <code>isPrivate: Boolean [0..1]</code> (kennzeichnet, ob das Zertifikat privat/geheim zu halten ist bzw. den privaten Schlüssel repräsentiert).</li>\n<li><strong><code>DdsProtectionKindEnum</code></strong> <em>(«enumeration»)</em>:</li>\n<li>Schutzarten gemäß OMG DDS Security Specification mit den Literalen:</li>\n<li><code>none</code>: Ungeschützte Übertragung.</li>\n<li><code>sign</code>: Integritätsschutz durch kryptografische Signatur.</li>\n<li><code>encryptAndSign</code>: Vertraulichkeit und Integrität durch Verschlüsselung und Signatur.</li>\n<li><code>signWithOriginAuthentication</code>: Signatur mit Authentifizierung des Nachrichtenursprungs.</li>\n<li><code>encryptAndSignWithOriginAuthentication</code>: Verschlüsselung und Signatur mit Authentifizierung des Nachrichtenursprungs.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell handelt, manifestiert sich das Verhalten zur Laufzeit während des Plattform-Bootstraps und Verbindungsaufbaus:</p>\n<ol class=\"fig-list\">\n<li><strong>Deployment & Initialisierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Plattform-Management-/Execution-Management-Dienst parst das Manifest.</li>\n<li>Der DDS-Binding-Stack (z. B. RTI Connext Drive, FastDDS) instantiiert den <code>DomainParticipant</code> innerhalb des durch <code>DdsDomainRange</code> [min..max] definierten Bereichs.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kryptografische Vorkonfiguration:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Abruf des privaten Identitätszertifikats (<code>identity</code>) und der Root-CAs (<code>identityCertificateAuthority</code>, <code>permissionCertificateAuthority</code>) über die Schnittstellen von <code>ara::crypto</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>DDS Security Plugin Handshake (OMG DDS-SEC):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Authentication:</strong> Validierung der Remote-Participants gegen <code>identityCertificateAuthority</code>. Bei Fehlschlag Prüfung von <code>allowUnauthenticatedParticipants</code>.</li>\n<li><strong>Access Control:</strong> Auswertung von <code>enableJoinAccessControl</code> und Validierung von Berechtigungstoken gegen <code>permissionCertificateAuthority</code>.</li>\n<li><strong>Crypto Exchange:</strong> Aushandlung symmetrischer Sitzungsschlüssel basierend auf den Vorgaben für <code>discoveryProtectionKind</code>, <code>livelinessProtectionKind</code> und <code>rtpsProtectionKind</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Verkehrsabsicherung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Jeder RTPS-Submessage-Header bzw. Payload wird entsprechend des konfigurierten <code>DdsProtectionKindEnum</code> signiert, verschlüsselt oder ungeschützt übertragen. Bei Sicherheitsverletzungen erfolgt der Abbruch des Handshakes und optionales Reporting an das IDS (Intrusion Detection System / <code>ara::idsm</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Modellierung (ARXML):</strong></li>\n<li>Durch Vererbung von <code>UploadablePackageElement</code> können <code>DdsSecureGovernance</code> und Service-Mappings unabhängig von der Applikations-Binärdatei über das Update and Configuration Management (<code>ara::ucm</code>) aktualisiert werden (z. B. bei CA-Rollover oder geänderten Schutzklassen).</li>\n<li><strong>Stack- und Middleware-Entwickler:</strong></li>\n<li>Der DDS-Code-Generator muss aus <code>DdsSecureGovernance</code> die standardisierten OMG-DDS-SEC-XML-Dokumente (<code>governance.xml</code> und <code>permissions.xml</code>) generieren oder native Middleware-Properties konfigurieren.</li>\n<li><code>isPrivate = true</code> am <code>CryptoCertificate</code> signalisiert dem Deployment-Tooling, dass neben dem Zertifikat auch ein privater Schlüssel (Key Slot) im Crypto Stack gebunden sein muss.</li>\n<li><strong>Ressourcen- und Laufzeitimplikationen (Embedded/Safety):</strong></li>\n<li>Die Wahl von <code>encryptAndSignWithOriginAuthentication</code> in <code>rtpsProtectionKind</code> führt zu signifikantem CPU-Overhead und Latenzanstieg pro RTPS-Paket; erfordert zwingend Hardware-Krypto-Beschleunigung (z. B. über HSM/SHE-Anbindung an <code>ara::crypto</code>).</li>\n<li>Eine Fehlkonfiguration der <code>DdsDomainRange</code> verhindert die Discovery zwischen Service-Provider und Consumer vollständig, ohne dass funktionale Kommunikationsfehler auf API-Ebene (<code>ara::com</code>) differenziert gemeldet werden.</li>\n</ul>"}], "trans": [{"from": "FIG-74b7d013a949c865", "to": "FIG-e285811befa1ac49", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-e285811befa1ac49", "to": "FIG-5d47f54366f774d6", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>ServiceInstanceToMachineMapping: Metaklassen-Generalisierung von UploadablePackageElement auf UploadableDesignElement geändert.</li>\n<li>AdaptivePlatformServiceInstance: Metaklassen-Generalisierung von UploadablePackageElement auf UploadableDesignElement geändert.</li>\n<li>DdsSecureGovernance: Metaklassen-Generalisierung von UploadablePackageElement auf UploadableDesignElement geändert.</li>\n<li>SecureComProps: Zusätzliche Metaklassen-Generalisierung UploadableDesignElement ergänzt (neben ARElement).</li>\n</ul>"}, {"from": "FIG-5d47f54366f774d6", "to": "FIG-dec460e72c7d220d", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>DdsProtectionKindEnum: Im Enumerationsblock wurde die standardisierte UML-Fachbezeichnung literals oberhalb der Literale ergänzt.</li>\n</ul>"}, {"from": "FIG-dec460e72c7d220d", "to": "FIG-5a329285d1c21059", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
